window.ScripturaLexicons.BDAG_PART_0367 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-01\" data-source=\"BDAG\" data-search=\"ὑπέθηκα forma verbal remissão a ὑποτίθημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπέθηκα</td><td>forma verbal</td><td>remissão a ὑποτίθημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-02\" data-source=\"BDAG\" data-search=\"ὑπείκω verbo ceder; submeter-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπείκω</td><td>verbo</td><td>ceder; submeter-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-03\" data-source=\"BDAG\" data-search=\"ὑπέλαβον forma verbal remissão a ὑπολαμβάνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπέλαβον</td><td>forma verbal</td><td>remissão a ὑπολαμβάνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-04\" data-source=\"BDAG\" data-search=\"ὑπελείφθην forma verbal remissão a ὑπολείπω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπελείφθην</td><td>forma verbal</td><td>remissão a ὑπολείπω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-05\" data-source=\"BDAG\" data-search=\"ὑπέμεινα forma verbal remissão a ὑπομένω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπέμεινα</td><td>forma verbal</td><td>remissão a ὑπομένω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-06\" data-source=\"BDAG\" data-search=\"ὑπεμνήσθην forma verbal remissão a ὑπομιμνῄσκω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπεμνήσθην</td><td>forma verbal</td><td>remissão a ὑπομιμνῄσκω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-07\" data-source=\"BDAG\" data-search=\"ὑπεναντίος, α, ον adjetivo oposto; contrário; hostil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπεναντίος, α, ον</td><td>adjetivo</td><td>oposto; contrário; hostil</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-08\" data-source=\"BDAG\" data-search=\"ὑπενεγκεῖν forma verbal remissão a ὑποφέρω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπενεγκεῖν</td><td>forma verbal</td><td>remissão a ὑποφέρω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-09\" data-source=\"BDAG\" data-search=\"ὑπεξέρχομαι verbo sair discretamente; sair secretamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπεξέρχομαι</td><td>verbo</td><td>sair discretamente; sair secretamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-10\" data-source=\"BDAG\" data-search=\"ὑπέπλευσα forma verbal remissão a ὑποπλέω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπέπλευσα</td><td>forma verbal</td><td>remissão a ὑποπλέω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-11\" data-source=\"BDAG\" data-search=\"ὑπέρ preposição; advérbio por; em benefício de; em lugar de; acima de; mais do que BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπέρ</td><td>preposição; advérbio</td><td>por; em benefício de; em lugar de; acima de; mais do que</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-12\" data-source=\"BDAG\" data-search=\"ὑπεραγάλλομαι verbo depoente alegrar-se; exultar grandemente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπεραγάλλομαι</td><td>verbo depoente</td><td>alegrar-se; exultar grandemente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-13\" data-source=\"BDAG\" data-search=\"ὑπεράγαν advérbio além da medida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπεράγαν</td><td>advérbio</td><td>além da medida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-14\" data-source=\"BDAG\" data-search=\"ὑπεραγαπάω verbo amar muito ternamente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπεραγαπάω</td><td>verbo</td><td>amar muito ternamente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-15\" data-source=\"BDAG\" data-search=\"ὑπεραίρω verbo exaltar-se; ensoberbecer-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπεραίρω</td><td>verbo</td><td>exaltar-se; ensoberbecer-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-16\" data-source=\"BDAG\" data-search=\"ὑπέρακμος, ον adjetivo passado o apogeu; no apogeu sexual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπέρακμος, ον</td><td>adjetivo</td><td>passado o apogeu; no apogeu sexual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-17\" data-source=\"BDAG\" data-search=\"ὑπεράνω advérbio; preposição acima de BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπεράνω</td><td>advérbio; preposição</td><td>acima de</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-18\" data-source=\"BDAG\" data-search=\"ὑπερασπίζω verbo proteger BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπερασπίζω</td><td>verbo</td><td>proteger</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-19\" data-source=\"BDAG\" data-search=\"ὑπερασπισμός, οῦ, ὁ substantivo masculino proteção BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπερασπισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>proteção</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0367-20\" data-source=\"BDAG\" data-search=\"ὑπερασπιστής, οῦ, ὁ substantivo masculino protetor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ὑπερασπιστής, οῦ, ὁ</td><td>substantivo masculino</td><td>protetor</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0367-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέθηκα</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπέθηκα</span> v. <span class=\"greek\">ὑποτίθημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπείκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπείκω</span> (Hom. et al.) primariamente ‘retirar-se, ceder a’, depois por extensão fig. ceder à autoridade de alguém, ceder, dar lugar, submeter-se (Hom. et al.; 4 Macc 6:35; TestSol 12:1 C; TestAbr A 9 p. 86, 30 [Stone p. 20]; Ath., R. 15 p. 66, 34 <span class=\"greek\">σῶμα</span> … <span class=\"greek\">ταῖς</span> <span class=\"greek\">τῆ</span>· <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">ἡνίαις</span> <span class=\"greek\">ὑπεῖκον</span>) com dat. da pessoa a quem se submete (Hom.; Pla., Leg. 4, 717d; Sextus 17; cf. Philo, Mos. 1, 156) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:17</a>.—DELG s.v. <span class=\"greek\">εἴκω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέλαβον</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπέλαβον</span> v. <span class=\"greek\">ὑπολαμβάνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπελείφθην</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπελείφθην</span> v. <span class=\"greek\">ὑπολείπω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέμεινα</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπέμεινα</span> v. <span class=\"greek\">ὑπομένω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπεμνήσθην</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπεμνήσθην</span> v. <span class=\"greek\">ὑπομιμνῄσκω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπεναντίος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπεναντίος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (Hes., Hdt. et al.) principalmente oposto, contrário, hostil (Thu. 2, 2, 2; Pla., Tht. 176a; Demosth. 24, 108 al.; inscr. [p. ex. ISmyrnaMcCabe 0421, 8], papiros; Jos., C. Ap. 2, 180) <span class=\"greek\">τινί</span> contra alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:14</a>. Subst. <span class=\"greek\">ὁ</span> <span class=\"greek\">ὑπεναντίος</span> o oponente (X.; Polyb. 1, 11, 14; Plut., Thes. 6 [13, 2]; inscr.; POxy 1151, 55; LXX; TestSol 8:10; predominantemente no pl.) <span class=\"greek\">οἱ</span> <span class=\"greek\">ὑπεναντίοι</span> os adversários (X., Cyr. 1, 6, 38) de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:27</a> (cf. Is 26:11).—DELG s.v. <span class=\"greek\">ἄντα</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπενεγκεῖν</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπενεγκεῖν</span> v. <span class=\"greek\">ὑποφέρω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπεξέρχομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπεξέρχομαι</span> 2 aor. <span class=\"greek\">ὑπεξῆλθον</span> sair discretamente/secretamente (Pla. et al.; Plut., Lucullus 502 [16, 7]; Lucian, Dial. Mar. 2, 4; Cass. Dio 38, 17; JosAs 24:11; Jos., Vi. 21, Ant. 14, 16) MPol 5:1a. Com indicação do destino (Hdt. 8, 36 <span class=\"greek\">ἐς</span> <span class=\"greek\">Ἄμφισσαν</span>) <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀγρίδιον</span> 5:1b.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέπλευσα</h1><div class=\"entry-meta\"><span>forma verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπέπλευσα</span> v. <span class=\"greek\">ὑποπλέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρ</h1><div class=\"entry-meta\"><span>preposição; advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπέρ</span> (Hom.+) prep. com gen. e ac. (lit. s.v. <span class=\"greek\">ἀνά</span>, início. Além disso, para <span class=\"greek\">ὑπέρ</span>: LWenger, Die Stellvertretung im Rechte der Papyri 1896; ARobertson, The Use of <span class=\"greek\">ὑπέρ</span> in Business Documents in the Papyri: Exp. 8th ser., 28, 1919, 321–27). O sentido loc. ‘sobre, acima de’ não se encontra em nossa literatura (tampouco na LXX, mas em JosAs 14:4; ApcEsdr 1:9; Just., Tat., Ath.), mas aparece em sentidos não literais. Os mss. frequentemente oscilam entre <span class=\"greek\">ὑπέρ</span> e <span class=\"greek\">περί</span>; v. A3 abaixo.</p><p class=\"entry-text\">A. com gen.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> marcador que indica que uma atividade ou acontecimento se dá no interesse de alguma entidade, por, em benefício de, por amor de alguém/algo.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> com gen. de pessoa ou coletividade humana</p><p class=\"entry-text\"><span class=\"greek\">α</span>. depois de palavras que exprimem pedido, oração etc. Depois dos verbos <span class=\"greek\">δέομαι</span> (v. esse verbete, b), <span class=\"greek\">εὔχομαι</span> (v. esse verbete, 1), <span class=\"greek\">προσεύχομαι</span> (v. esse verbete), <span class=\"greek\">ἐντυγχάνω</span> (v. esse verbete, 1a; cf. b), <span class=\"greek\">ὑπερεντυγχάνω</span> (v. esse verbete), <span class=\"greek\">λιτανεύω</span> (v. esse verbete) etc. Depois dos substantivos <span class=\"greek\">δέησις</span> (v. esse verbete, final) e <span class=\"greek\">προσευχή</span> (v. esse verbete, 1). V. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:1f</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. depois de palavras e expressões que denotam trabalhar, cuidar, preocupar-se com. Depois dos verbos <span class=\"greek\">ἀγρυπνέω</span> (v. esse verbete, 2), <span class=\"greek\">ἀγωνίζομαι</span> (v. esse verbete, 2b), <span class=\"greek\">μεριμνάω</span> (v. esse verbete, 2), <span class=\"greek\">πρεσβεύω</span> (v. esse verbete) etc. Depois dos substantivos <span class=\"greek\">ζῆλος</span> (v. esse verbete, 1), <span class=\"greek\">σπουδή</span> (v. esse verbete, 2), <span class=\"greek\">ἔχειν</span> <span class=\"greek\">πόνον</span> (<span class=\"greek\">πόνος</span> 1). <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">διάκονος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:7</a>.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. depois de expressões relativas a sacrifício: <span class=\"greek\">ἁγιάζω</span> (v. esse verbete, 2), <span class=\"greek\">ἁγνίζομαι</span> (v. <span class=\"greek\">ἁγνίζω</span> 3). <span class=\"greek\">τὸ</span> <span class=\"greek\">πάσχα</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἑτύθη</span> <span class=\"greek\">Χριστός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:7</a> v.l. <span class=\"greek\">ἕως</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">προσηνέχθη</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">ἑκάστου</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">προσφορά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:26</a> (<span class=\"greek\">προσφέρω</span> 2a).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:7</a>.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. em geral <span class=\"greek\">εἶναι</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> ser por alguém, estar do lado de alguém (PIand 16, 8 <span class=\"greek\">τὸ</span> <span class=\"greek\">νόμιμον</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἐστιν</span>.—Op. <span class=\"greek\">εἶναι</span> <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 8:31</a>.—<span class=\"greek\">ἐπιτρέπεταί</span> <span class=\"greek\">σοι</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">σεαυτοῦ</span> <span class=\"greek\">λέγειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:1</a> v.l. (em lugar de <span class=\"greek\">περί</span>). <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἑνὸς</span> <span class=\"greek\">φυσιοῦσθε</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἑτέρου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:6b</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:11ab</a>; 5:20b (<span class=\"greek\">δεόμεθα</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">Χριστοῦ</span>=como auxiliares de Cristo vos rogamos. Também provável é: rogamo-vos por Cristo ou em nome de Cristo [Apollon. Rhod. 3, 701 <span class=\"greek\">λίσσομ</span>’ <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">μακάρων</span>=pelos deuses, em imitação de Il. 22, 338.—Theaetetus, III a.C.: Anth. Pal. 7, 499, 2]). <span class=\"greek\">τοῦτο</span> <span class=\"greek\">φρονεῖν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ὑμῶν</span> estar assim disposto em benefício de todos vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:7</a> (talvez simplesmente=acerca de; v. 3 abaixo); cf. 4:10 (pensar em mim = cuidar de mim, interessar-se por mim).</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. depois de expressões de sofrimento, morte, dedicação de si mesmo etc. (JosAs 28:1 <span class=\"greek\">κύριος</span> <span class=\"greek\">πολεμεῖ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">Ἀσενεθ</span> ‘contra nós em benefício de Asenet’; ApcEsdr 6:18 p. 31, 28 Tdf. <span class=\"greek\">δικάζεσθαι</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">γένους</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span>) <span class=\"greek\">ἀποθνῄσκειν</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> morrer por alguém ou algo (<span class=\"greek\">ἀποθνῄσκω</span> 1a<span class=\"greek\">α</span>; também Jos., Ant. 13, 6) J 11:50–52; 18:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:7ab</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">τίθησιν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τινος</span> (cf. Jos., Bell. 2, 201; Sir 29:15; ApcSed 1:5; Ar. 15, 10; Mel., P. 103, 791) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:11</a>, 15; 13:37f; 15:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:16b</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:1</a>, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:24a</a>.—Assim esp. da morte de Cristo (já referida, ao menos em parte, em algumas das passagens já mencionadas. V. também acima 1a<span class=\"greek\">γ</span> e abaixo 1c) por, em benefício da humanidade, do mundo etc.: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:19f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:6</a>, 8; 8:32; 14:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:13</a> (onde a pergunta hipotética <span class=\"greek\">μὴ</span> <span class=\"greek\">Παῦλος</span> <span class=\"greek\">ἐσταυρώθη</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὑμῶν</span>; foi escolhida por nenhuma outra razão senão sua referência à morte redentora de Cristo); 11:24; 15:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:20</a>; 3:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:10</a> (v.l. <span class=\"greek\">περί</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:9</a>; 6:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:21</a> (v.l. <span class=\"greek\">περί</span>); 3:18a v.l.; 18b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:16a</a>; MPol 17:2ab (Just., A I, 50, 1 <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">γενόμενος</span> <span class=\"greek\">ἄνθρωπος</span>).—AMetzinger, Die Substitutionstheorie u. das atl. Opfer, Biblica 21, ’40, 159–87, 247–72, 353–77; EBlakeney, ET 55, ’43/44, 306.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> com gen. de coisa, caso em que deve ser traduzido de diversas maneiras <span class=\"greek\">ὑπὲρ</span> (<span class=\"greek\">τῶν</span>) <span class=\"greek\">ἁμαρτιῶν</span> a fim de expiar (os) pecados ou removê-los <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:1b</a>; 7:27; 9:7 (aqui <span class=\"greek\">ὑπὲρ</span> … <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγνοημάτων</span>); 10:12; B 7:3, 4 (dito profético de origem desconhecida), 5f.—<span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">ζωῆς</span> para trazer vida ao mundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:51</a>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> para revelar a glória de Deus 11:4. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματος</span> <span class=\"greek\">αὐτοῦ</span> (cf. Sb 7681, 7 [312 d.C.] <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματός</span> <span class=\"greek\">μου</span>=em benefício de) para propagar seu nome <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:5</a>; cf. 3J 7. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἀληθείας</span> <span class=\"greek\">θεοῦ</span>=a fim de mostrar que as promessas de Deus são verdadeiras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:8</a>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">παρακλήσεως</span> a fim de vos consolar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:6ab</a>. Cf. 12:19. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">ὑμῶν</span> para o fortalecimento de vossa fé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:2</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> em lugar de, em vez de, em nome de (Eur.; Polyb. 3, 67, 7; ApcEsdr 1:11 p. 25, 3 Tdf.; Jos., C. Ap. 2, 142; Just., D. 95, 2.—Nos papiros muito frequentemente <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">αὐτοῦ</span> para explicar que o escritor escreve ‘como representante de’ uma pessoa analfabeta; Dssm. LO 285, 2 [LAE 335, 4]; outros exemplos de papiros em DWallace, Greek Grammar Beyond the Basics ’96, 384–86) <span class=\"greek\">ἵνα</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">σοῦ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">διακονῇ</span> Phlm 13. Às vezes o significado em lugar de funde-se com em benefício de, por causa de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:3</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">βαπτιζόμενοι</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">νεκρῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:29a</a> é discutido; cf. 29b (v. a lit. s.v. <span class=\"greek\">βαπτίζω</span> 2c; também KBornhäuser, Die Furche 21, ’34, 184–87; JWhite, JBL 116, ’97, 487–99 [esp. 497f] favorece um sentido causal). <span class=\"greek\">εἷς</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἀπέθανεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:14</a>; cf. 15ab, 21 (Eur., Alc. 701 <span class=\"greek\">κατθανεῖν</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">σου</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> marcador da causa motriz ou razão, por causa de, por amor de, por (Diod S 10, 21, 2 <span class=\"greek\">τὴν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτημάτων</span> <span class=\"greek\">τιμωρίαν</span>; escólio a Pind., O. 6, 154b [=OxfT 91]), com verbos de sofrimento, dando a razão deste <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:41</a>; 9:16; 21:13; <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:29ab</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:5</a>; <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἀποθνῄσκω</span> IRo 4:1. Igualmente empregado com substantivos que denotam sofrimento <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">Χριστοῦ</span> por amor de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:10</a>.—<span class=\"greek\">εὐχαριστεῖν</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> dar graças por algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:20</a>; D 9:2; 10:2 (cf. Sb 3926, 12 [I a.C.] <span class=\"greek\">τὸ</span> <span class=\"greek\">κατεσκευασμένον</span> <span class=\"greek\">ὑπὲρ</span> [=em gratidão por] <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡμετέρας</span> <span class=\"greek\">σωτηρίας</span> <span class=\"greek\">Ἰσιδεῖον</span>; Just., A I, 65, 3). <span class=\"greek\">δοξάζειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τινος</span> louvar a Deus por algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:9</a>.—<span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τούτου</span> com referência a algo (Synes., Ep. 67 p. 209c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:8</a>.—Este é provavelmente o lugar para <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐδοκίας</span> tendo em vista o beneplácito (de Deus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:13</a> (<span class=\"greek\">εὐδοκία</span> 1).</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> marcador de conteúdo geral, quer de discurso, quer de atividade mental, acerca de, a respeito de (aproximadamente equivalente a <span class=\"greek\">περί</span> [<span class=\"greek\">τινος</span>], com que é frequentemente intercambiado nos mss.; v. Kühner-G. I p. 487 [com exemplos de Hom., Pla. et al.]. Também bastante comum em Polyb., Diod S, Dionys. Hal., Joseph., inscr. [p. ex. ISardGauthier 2, 3 ‘escrever acerca de’] e papiros [Schmidt 396]; mas Ath. distingue <span class=\"greek\">λόγος</span> <span class=\"greek\">ὑπὲρ</span> [em defesa de] <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> de <span class=\"greek\">λόγος</span> <span class=\"greek\">περὶ</span> [acerca de] <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> R 1 p. 48, 19; Mlt. 105; Rdm.2 p. 140; Johannessohn, Präp 216–21; LDeubner, Bemerkungen z. Text der Vita Pyth. des Iamblichos: SBBerlAk ’35, XIX 27; 71), frequentemente ao mesmo tempo no sentido de ‘no interesse de’ ou ‘em benefício de’ <span class=\"greek\">οὗτός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">εἶπον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:30</a> (v.l. <span class=\"greek\">περί</span>). <span class=\"greek\">Ἠσαί̈ας</span> <span class=\"greek\">κράζει</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰσραήλ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:27</a> (v.l. <span class=\"greek\">περί</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:8</a> (v.l. <span class=\"greek\">περί</span>); 5:12; 7:4, 14; 8:24; 9:2f; 12:5ab (em todas as passagens de 2 Cor exceto a primeira, dependente de <span class=\"greek\">καυχάομαι</span>, <span class=\"greek\">καύχημα</span>, <span class=\"greek\">καύχησις</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:4</a> (<span class=\"greek\">ἐγκαυχᾶσθαι</span>). Com referência a (Demosth. 21, 121) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:1</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">βεβαία</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὑμῶν</span> nossa esperança com referência a vós é inabalável <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:7</a> (<span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">ὑ</span>. <span class=\"greek\">τινος</span> ‘por algo’ Socrat., Ep. 6, 5 [p. 234, 28 Malherbe]).</p><p class=\"entry-text\">B. com ac. marcador de grau além daquele de uma escala de extensão comparada, no sentido de exceder, superar, acima de, além de, mais do que (assim sempre PsSol; TestAbr A 4 p. 81, 29 [Stone p. 10] al.; TestJob 38:6 <span class=\"greek\">τὰ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἡμᾶς</span>; JosAs 1:6 al.; Ath. 17, 1; 32, 1) <span class=\"greek\">κεφαλὴ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">πάντα</span> a Cabeça suprema <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.22\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:22</a> (Appian, Bell. Civ. 5, 74 §314 <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἅπαντα</span>). <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">δύναμιν</span> além das próprias forças <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:8</a>; cf. 8:3 v.l. (OGI 767, 19f <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">δύναμιν</span>; Cyranides p. 63, 22 <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">λόγον</span>). Também <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">δύνασθε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:13</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">γέγραπται</span> não (ir) além do que está escrito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:6a</a> (v. WLütgert, Freiheitspredigt u. Schwarmgeister in Korinth 1908, 97ff; ASchlatter, Die korinth. Theologie 1914, 7ff; OLinton, StKr 102, 1930, 425–37; LBrun, ibid. 103, ’31, 453–56; PWallis, TLZ 75, ’50, 506–8; ALegault, NTS 18, ’71/72, 227–31; PMarshall, Hybrists Not Gnostics in Corinth: SBLSP 23, 84, 275–87; sobre a provável imagem de um exercício escolar em que as crianças aprendem a permanecer entre as linhas, v. RTyler, CBQ 60, ’98, 97–103; um documento público fundacional contendo estatutos, JHanges, JBL 117, ’98, 275–98 [papiros e inscr.]). <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">λέγω</span> <span class=\"greek\">ποιήσεις</span> farás ainda mais do que peço Phlm 21. <span class=\"greek\">ὑπέρ</span> <span class=\"greek\">τι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὑπερβολὴν</span> <span class=\"greek\">ὑπερευφραίνομαι</span> sinto uma alegria extraordinária e arrebatadora B 1:2.—Depois de adj. no compar. ou superl. em lugar de <span class=\"greek\">ἤ</span> do que: principalmente assim depois do compar. (Judg 11:25 B; 15:2 B; 18:26 B; 3 Km 19:4; Ps 18:11; Hab 1:8) <span class=\"greek\">τομώτερος</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">μάχαιραν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:12</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.43\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:43</a> v.l.; MPol 18:2. Em uma afirmação excepcionalmente condensada: <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἀποστόλους</span> <span class=\"greek\">ὄντας</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἁμαρτίαν</span> <span class=\"greek\">ἀνομωτέρους</span> os apóstolos, que eram mais iníquos do que (as pessoas que cometem) qualquer pecado, todo e qualquer pecado B 5:9; raramente depois do superl. (TestAbr A 2 p. 78, 25 [Stone p. 4]) <span class=\"greek\">γλυκυτάτη</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μέλι</span> Hm 5, 1, 6. Igualmente depois de verbos que exprimem a ideia de comparação <span class=\"greek\">ἡσσώθητε</span> (=<span class=\"greek\">ἐγένεσθε</span> <span class=\"greek\">ἥσσονες</span>) <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">λοιπὰς</span> <span class=\"greek\">ἐκκλησίας</span>, fostes tratados pior do que as outras igrejas? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:13</a>.—‘Mais do que’ assume também o sentido de mais elevado ou excelente ou glorioso do que; como aquele que está fora do tempo (<span class=\"greek\">ἄχρονος</span>), Cristo é chamado <span class=\"greek\">ὁ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">καιρόν</span> aquele que é exaltado além do tempo IPol 3:2. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">θάνατον</span> exaltado acima da morte ISm 3:2. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">μαθητὴς</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">διδάσκαλον</span> um discípulo não é superior a seu mestre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:24a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:40</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:24b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:9</a>. <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">δοῦλον</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">δοῦλον</span> não mais como escravo, mas como algo melhor do que um escravo Phlm 16. <span class=\"greek\">τῷ</span> <span class=\"greek\">δυναμένῳ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ποιῆσαι</span> a (Deus) que pode fazer coisas maiores do que tudo (quanto podemos pedir ou imaginar) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:20</a>.—Mais do que (PsSol 17:43; TestGad 7:1) <span class=\"greek\">ἀγαπᾶν</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχήν</span> <span class=\"greek\">μου</span> (JosAs 13:11) B 1:4; cf. 4:6; 19:5; D 2:7. <span class=\"greek\">φιλεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:37ab</a>. <span class=\"greek\">ἀρέσει</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">μόσχον</span> 1 Cl 52:2 (Ps 68:32). <span class=\"greek\">λάμπειν</span> IEph 19:2. <span class=\"greek\">προκόπτειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:14</a>. <span class=\"greek\">στίλβειν</span> Hs 9, 2, 2.</p><p class=\"entry-text\">C. uso adv. ainda mais. O uso adv. de <span class=\"greek\">ὑπέρ</span> é, até agora, quase desconhecido fora do NT (mas v. L-S-J-M s.v. <span class=\"greek\">ὑπέρ</span> E; Schwyzer II 518; Ursing 49 cita de um ms. de Esopo <span class=\"greek\">ὅπερ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἀπεδέξατο</span>, onde todos os outros mss. têm <span class=\"greek\">μᾶλλον</span> [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:4</a> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">μᾶλλον</span>]. Sobre o uso adv. de outras preposições v. Kühner-G. I p. 526f). <span class=\"greek\">διάκονοι</span> <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">εἰσιν</span>; <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἐγώ</span> são eles auxiliares de Cristo? Eu o sou ainda mais (do que eles) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:23</a> (W-H. acento <span class=\"greek\">ὕπερ</span>; v. Mlt-Turner 250). Wallis (v. B acima) classifica <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:6</a> aqui.—RBieringer: The Four Gospels, Festschr. FNeirynck, ed. FvanSegbroeck et al. ’92, I 219–48. Sobre <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἄγαν</span>, <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἐκεῖνα</span>, <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἐκπερισσοῦ</span>, <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">λίαν</span> v. <span class=\"greek\">ὑπεράγαν</span>, <span class=\"greek\">ὑπερέκεινα</span>, <span class=\"greek\">ὑπερεκπερισσοῦ</span> (-<span class=\"greek\">ῶς</span>), <span class=\"greek\">ὑπερλίαν</span>.—DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπεραγάλλομαι</h1><div class=\"entry-meta\"><span>verbo depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπεραγάλλομαι</span> dep. alegrar-se/exultar grandemente <span class=\"greek\">ὑπεραγαλλόμενος</span> com a mais elevada alegria IPhld 5:1.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπεράγαν</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπεράγαν</span> adv. (<span class=\"greek\">ὑπέρ</span> + <span class=\"greek\">ἄγαν</span>; Strabo 3, 2, 9; Aelian, NA 3, 38; Vett. Val. p. 63, 5; Diog. L. 3, 26; 2 Macc 10:34. Escrito separadamente já em Eur., Med. 627.—B-D-F §116, 3) além da medida 1 Cl 56:2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπεραγαπάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπεραγαπάω</span> 1 aor. <span class=\"greek\">ὑπερηγάπησα</span> (Demosth. 23, 196; Aristot., EN 9, 7, 1168a, 1; Cass. Dio 77, 22, 1; Herodian 4, 7, 4; Aristaen., Ep. 1, 19; 2, 16 <span class=\"greek\">σε</span>; Eunap. p. 67; Jos., Ant. 1, 222; 12, 195) amar muito ternamente <span class=\"greek\">τινά</span> alguém (Plut., Ages 616 [35, 2]; Ps.-Callisth. 2, 21, 2) B 5:8.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπεραίρω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπεραίρω</span> aor. 3 sg. <span class=\"greek\">ὑπερῆρεν</span> e <span class=\"greek\">ὑπερῇραν</span> LXX. Pass.: fut. 3 sg. <span class=\"greek\">ὑπεραρθήσεται</span> Ps 71:16; aor. 3 sg. <span class=\"greek\">ὑπερῄρθη</span> 2 Ch 32:23; part. perf. n. <span class=\"greek\">ὑπερῃρμένον</span> (Just., D. 91, 2) (Aeschyl., Pla. et al.; inscr., papiros, LXX, EpArist; Jos., C. Ap. 2, 223; Just., D. 91, 2 em vários sentidos) em nossa literatura somente <span class=\"greek\">ὑπεραίρομαι</span> ter um senso indevido da própria importância, elevar-se, exaltar-se, ensoberbecer-se (Aristaen. 1, 17; Anth. Pal. 5, 299, 5; 2 Macc 5:23 [com dat.]) <span class=\"greek\">ἐπὶ</span> com ac. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:4</a>. Abs. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:7ab</a> (canção popular bizantina em Theophanes Conf. [VIII d.C.], Chron. 283, 19ff deBoor [v. KKrumbacher, Byz. Lit.2 1897, 792] <span class=\"greek\">δὸς</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">κρανίου</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὑπεραίρηται</span>).—DELG s.v. 1 <span class=\"greek\">ἀείρω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπέρακμος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπέρακμος</span>, <span class=\"greek\">ον</span> (Soranus, Hesych., Suda) de <span class=\"greek\">ἀκμή</span>=ponto culminante ou apogeu do desenvolvimento de uma pessoa (<span class=\"greek\">ἀκ</span>. neste sentido em Pla., Rep. 5, 460e; Philo, Leg. All. 1, 10) em nossa literatura somente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.36\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:36</a>. Dependendo da compreensão desta passagem (v. <span class=\"greek\">γαμίζω</span>), o termo pode aplicar-se tanto a uma mulher quanto a um homem.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> Entendido temporalmente e como termo indicativo da condição de uma mulher: passado o apogeu, além da idade núbil, passada a flor da juventude (cf. Soranus p. 15, 8.—Diod S 32, 11, 1 fala da <span class=\"greek\">ἀκμὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡλικίας</span> de uma mulher e em 34 + 35 Fgm. 2, 39 emprega <span class=\"greek\">ἀκμή</span> para designar a flor da juventude de uma <span class=\"greek\">παρθένος</span>.—Lycon [III a.C.], Fgm. 27 Wehrli [em Diog. L. 5, 65], compadece-se do pai de uma <span class=\"greek\">παρθένος</span> que, por causa da exiguidade de seu dote, <span class=\"greek\">ἐκτρέχουσα</span> [=ultrapassa] <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀκμαῖον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἡλικίας</span> <span class=\"greek\">καιρόν</span>). Assim, p. ex., Tyndale, Phillips, KJV, Jerusalem Bible.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> Outros intérpretes concentram-se na força intensificadora de <span class=\"greek\">ὑπέρ</span>, ‘excessivamente’ (frequentemente encontrada em compostos, como em <span class=\"greek\">ὑπέρκαλος</span> ‘extraordinariamente belo’ e termos afins Pollux 3, 71). Em nossa passagem, então, <span class=\"greek\">ὑπέρακμος</span> significa estar no apogeu sexual e pode aplicar-se a uma mulher (assim, aparentemente, L-S-J-M ‘sexualmente bem desenvolvida’) ou a um homem (cf. Diod S 36, 2, 3 <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔρως</span> de um homem apaixonado <span class=\"greek\">ἤκμαζεν</span> e tornou-se irresistível), com fortes paixões (REB e NRSV ‘se suas paixões são fortes’).—Cf. DELG s.v. <span class=\"greek\">ἀκ</span>-p. 44. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπεράνω</h1><div class=\"entry-meta\"><span>advérbio; preposição</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπεράνω</span> adv. (Aristot.+; inscr., papiros, LXX, TestAbr A) (muito) acima, funciona como prep. com gen. (B-D-F §215, 2; Rob. 646f) de lugar (Archimed. II 318, 6 Heib.; Eratosth. p. 46, 7; Ocellus Luc. c. 36 <span class=\"greek\">ὑπ</span>. <span class=\"greek\">σελήνης</span>; Diod S 20, 23, 1; escólio a Apollon. Rhod. 2, 160b; Ezk 43:15; TestAbr A 7 p. 83f [Stone p. 14f]; ViDa 21 [p. 79, 12 Sch.]; Jos., Ant. 3, 154) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:5</a>.—De posição hierárquica, poder etc. (Lucian, Demon. 3; Dt 28:1; Philo, Conf. Lingu. 137; TestLevi 3:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:21</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερασπίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπερασπίζω</span> fut. <span class=\"greek\">ὑπερασπιῶ</span> LXX, 3 sg. <span class=\"greek\">ὑπερασπίσει</span> Pr 30:5 A (Polyb. 6, 39, 6 al.; Dionys. Hal. 6, 12, 2; inscr.; Gen 15:1; 4 Km 19:34; Pr 2:7; TestBenj 4:5; JosAs 28:10 [com gen.]; também cap. 11 cód. A [p. 54, 15 Bat.]; Philo) lit. ‘sustentar um escudo sobre’ (como proteção, v. Polyb. e D. H. acima) metaf. proteger, <span class=\"greek\">αὐτούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:27</a> P74.—DELG s.v. <span class=\"greek\">ἀσπίς</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερασπισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπερασπισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (Ps 17:36; v. <span class=\"greek\">ὑπερασπίζω</span>) proteção 1 Cl 56:16.—B.-<span class=\"greek\">σις</span> 1410.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0367-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑπερασπιστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">ὑπερασπιστής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">ὑπερασπίζω</span>; LXX; PsSol 7:7; JosAs 12:11 [<span class=\"greek\">κύριος</span> <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">τῶν</span> <span class=\"greek\">διωκομένων</span>]; Philo, Ebr. 111; Lydus, Mag. 1, 46 p. 48, 22 W.; Hesych., Suda; Jos., Bell. 1, 627) protetor 1 Cl 45:7.—DELG s.v. <span class=\"greek\">ἀσπίζω</span>.</p></section></article>"};
